        (1, "Dağılma dönemi", "1821 Yunan isyanının fikrî hazırlığında etkili olan cemiyet hangisidir?", "Filiki Eterya Cemiyetidir."),
        (1, "Dağılma dönemi", "1829 Edirne Antlaşması'nın Yunanistan açısından sonucu nedir?", "Yunanistan bağımsız hâle gelmiştir."),
        (1, "Dağılma dönemi", "Kütahya Antlaşması ile Mehmet Ali Paşa'ya verilen valiliklerden ikisini yazınız.", "Mısır ve Girit valiliklerine ek olarak Şam valiliği; oğlu İbrahim Paşa'ya da Cidde ve Adana valilikleri verilmiştir."),
        (2, "Mısır Meselesi", "Hünkar İskelesi Antlaşması, Boğazlar bakımından hangi sonucu doğurmuştur?", "Boğazlar üzerinde Rusya'ya büyük üstünlük sağlayarak Osmanlı'nın Boğazlar üzerindeki son söz hakkını sınırlamıştır."),
        (2, "Mısır Meselesi", "1838 Baltalimanı Antlaşması'nın Osmanlı ekonomisine etkisi nedir?", "Gümrük oranları düşürülmüş, Osmanlı ekonomisi dışa bağımlı hâle gelmiştir."),
        (2, "Mısır Meselesi", "Nizip Savaşı'nın kaybedilmesinin hemen ardından Mısır Meselesi için toplanan konferans hangisidir?", "Londra Konferansı'dır."),
        (2, "Tanzimat", "Tanzimat Fermanı hangi düşünce akımının etkisiyle ilan edilmiştir?", "Osmanlıcılık düşünce akımının etkisiyle ilan edilmiştir."),
        (2, "Kırım Savaşı", "Kırım Savaşı sırasında Osmanlı Devleti'nin ilk kez dış borç aldığı devlet hangisidir?", "İngiltere'dir."),
        (2, "Kırım Savaşı", "Kırım Savaşı'nda modern hemşireliğin kurucusu sayılan kişi kimdir?", "Florence Nightingale'dir."),
        (2, "Kırım Savaşı", "1856 Paris Antlaşması ile Osmanlı Devleti bakımından öne çıkan iki karar nedir?", "Osmanlı Devleti Avrupa devletler hukukundan yararlanacak; toprak bütünlüğü Avrupa devletlerinin garantisi altına girecektir."),
        (2, "93 Harbi", "1878 Ayastefanos Antlaşması imzalanmasına rağmen yürürlüğe girmeyen ilk Osmanlı antlaşması hangisidir?", "Ayastefanos Antlaşması'dır."),
        (3, "Berlin Antlaşması", "Berlin Antlaşması ile Bulgaristan'ın idarî statüsü nasıl düzenlenmiştir?", "Bulgaristan üç bölgeye ayrılmış; ilk bölge Osmanlı'ya bağlı Bulgaristan Prensliği, ikinci bölge özerk Doğu Rumeli, üçüncü bölge ise ıslahat yapılacak Makedonya olmuştur."),
        (3, "Berlin Antlaşması", "Berlin Antlaşması ile Rusya'nın Bulgaristan üzerinden Akdeniz'e inmesi hangi yolla engellenmiştir?", "Büyük Bulgaristan'ın küçültülmesiyle engellenmiştir."),
        (3, "Berlin Antlaşması", "Berlin Antlaşması'nda Girit ve Bosna-Hersek için alınan kararlar nelerdir?", "Girit'te ıslahat yapılacak, Bosna-Hersek Osmanlı'ya bağlı kalacak fakat Avusturya tarafından yönetilecektir."),
        (3, "Berlin Antlaşması", "Berlin Antlaşması'nın Ermeni Meselesi üzerindeki etkisi nedir?", "Ermenilerin bulunduğu Girit ve Doğu Anadolu bölgelerinde ıslahat yapılması kararlaştırılarak mesele uluslararası nitelik kazanmıştır."),
        (3, "Dağılma dönemi", "Dömeke Meydan Muharebesi hangi devletle yapılmıştır?", "Yunanistan ile yapılmıştır."),
        (4, "Sened-i İttifak", "Sened-i İttifak hangi iki taraf arasında imzalanmıştır?", "II. Mahmut ile ayanlar arasında imzalanmıştır."),
        (4, "Sened-i İttifak", "Sened-i İttifak'ın Osmanlı siyasi tarihi bakımından en önemli sonucu nedir?", "Osmanlı padişahının mutlak otoritesi ilk kez sınırlandırılmış; ilk demokratikleşme hareketi sayılmıştır."),
        (4, "Sened-i İttifak", "Sened-i İttifak'ta ayanların üstlendiği iki görev nedir?", "Merkezî otoriteyi kabul etmek ve asker-vergi toplanmasına yardımcı olmaktır."),
        (4, "II. Mahmut", "II. Mahmut döneminde ayanlık kaldırılınca köy ve eyalet yönetiminde hangi görevliler kullanılmaya başlanmıştır?", "Köylere muhtar, eyaletlere müşir atanmıştır."),
        (4, "II. Mahmut", "Divan-ı Hümayun kaldırılınca yerine hangi kurum kurulmuştur?", "Heyet-i Vükela, yani Bakanlar Kurulu kurulmuştur."),
        (4, "II. Mahmut", "Takvim-i Vekayi'nin Osmanlı basın tarihi bakımından özelliği nedir?", "İlk resmî Osmanlı gazetesi olmasıdır."),
        (4, "II. Mahmut", "Müsadere usulünün kaldırılması hangi alandaki değişimi gösterir?", "Mülkiyet ve ekonomik alanda devlet müdahalesinin sınırlandırılmasını gösterir."),
        (5, "II. Mahmut", "Yeniçeri Ocağı'nın 1826'da kaldırılmasına verilen ad nedir?", "Vak'a-i Hayriye'dir."),
        (5, "II. Mahmut", "Yeniçeri Ocağı kaldırıldıktan sonra kurulan yeni ordu hangisidir?", "Asakir-i Mansure-i Muhammediye'dir."),
        (5, "II. Mahmut", "II. Mahmut döneminde yapılan ilk nüfus sayımının temel amaçları nelerdir?", "Askerlik çağına gelenleri tespit etmek ve vergi almak amaçlanmıştır."),
        (5, "II. Mahmut", "Mehterhane kaldırılınca yerine hangi müzik kurumu kurulmuştur?", "Mızıkayı Hümayun kurulmuştur."),
        (5, "II. Mahmut", "Yabancı dil bilen Müslüman diplomat yetiştirmek için kurulan kurum hangisidir?", "Tercüme Odalarıdır."),
        (5, "II. Mahmut", "II. Mahmut döneminde yerli malı kullanımını teşvik eden uygulamalardan birini yazınız.", "Memurların giyeceği kıyafetlerin yerli malı olması zorunlu tutulmuştur."),
        (6, "Tanzimat", "Tanzimat Fermanı'nın hazırlanmasında etkili olan devlet adamı kimdir?", "Mustafa Reşit Paşa'dır."),
        (6, "Tanzimat", "Tanzimat Fermanı'nın diğer adı nedir?", "Gülhane Hatt-ı Hümayunu'dur."),
        (6, "Tanzimat", "Tanzimat Fermanı ile güvence altına alınan üç temel hak nedir?", "Can, mal ve ırz güvenliğidir."),
        (6, "Tanzimat", "Tanzimat Fermanı'nın anayasal gelişme bakımından önemi nedir?", "Padişah kendi gücünün üstünde kanun gücünü kabul etmiş; anayasal sürecin ilk aşaması sayılmıştır."),
        (6, "Tanzimat", "Tanzimat Fermanı ile Islahat Fermanı'nı ayırmada kullanılan anahtar sözcük nedir?", "Tanzimat Fermanı için “herkes”, Islahat Fermanı için “gayrimüslim” vurgusu belirleyicidir."),
        (6, "Islahat Fermanı", "Islahat Fermanı hangi uluslararası gelişmenin ardından ilan edilmiştir?", "Paris Barış Konferansı kararlarında etkili olabilmek amacıyla ilan edilmiştir."),
        (6, "Islahat Fermanı", "Islahat Fermanı'nın ilanında Avrupa devletlerinin etkisi var mıdır?", "Evet. Avrupa devletlerinin baskısı etkili olmuştur."),
        (6, "Islahat Fermanı", "Islahat Fermanı'nın eşitlik bakımından Tanzimat'tan farkı nedir?", "Müslümanlarla gayrimüslimler arasında tam eşitlik sağlamayı hedeflemiştir."),
        (7, "Islahat Fermanı", "Islahat Fermanı ile cizye vergisi bakımından hangi değişiklik yapılmıştır?", "Cizye kaldırılmış; gayrimüslimlerin askerlik yapması veya bedel ödemesi düzenlenmiştir."),
        (7, "Islahat Fermanı", "Islahat Fermanı ile yabancılara tanınan mülkiyet hakkı nedir?", "Yabancılar Osmanlı sınırları içinde mülk sahibi olabilmiştir."),
        (7, "Tanzimat dönemi", "İlk özel gazete olan Tercüman-ı Ahval kimler tarafından çıkarılmıştır?", "Şinasi ve Agâh Efendi tarafından çıkarılmıştır."),
        (7, "Tanzimat dönemi", "İlk yarı resmî gazete hangisidir?", "Ceride-i Havadis'tir."),
        (7, "Tanzimat dönemi", "İlk demir yolu hangi hat üzerinde yapılmıştır?", "İzmir-Aydın arasında yapılmıştır."),
        (7, "Tanzimat dönemi", "Osmanlı'da ilk kâğıt para hangi adla basılmıştır?", "Kaime adıyla basılmıştır."),
        (7, "Tanzimat dönemi", "Bank-ı Osmanî'nin Osmanlı maliyesindeki ayırt edici özelliği nedir?", "İlk yabancı sermayeli İngiliz bankası olması ve para basma yetkisi almasıdır."),
        (8, "Abdülaziz", "Mecelle hangi padişah döneminde yürürlüğe girmiştir?", "Sultan Abdülaziz döneminde yürürlüğe girmiştir."),
        (8, "Abdülaziz", "Sultan Abdülaziz'in yurt dışına çıkışının Osmanlı tarihi bakımından özelliği nedir?", "Seyahat amacıyla yurt dışına çıkan ilk Osmanlı padişahı olmasıdır."),
        (8, "Abdülaziz", "Darülfünun hangi padişah döneminde açılmıştır?", "Sultan Abdülaziz döneminde açılmıştır."),
        (8, "Abdülaziz", "II. Abdülhamit döneminde ilan edilen ilk yazılı anayasanın adı nedir?", "Kanun-ı Esasi'dir."),
        (8, "I. Meşrutiyet", "I. Meşrutiyet ile açılan iki meclis hangileridir?", "Ayan Meclisi ve Mebusan Meclisidir."),
        (8, "I. Meşrutiyet", "Ayan Meclisi ile Mebusan Meclisi arasındaki seçilme farkı nedir?", "Ayan üyelerini padişah atar; Mebusan üyelerini halk seçer."),
        (9, "Kanun-ı Esasi", "1876 Kanun-ı Esasi'ye göre yasama yetkisi hangi kurumlara aittir?", "Ayan ve Mebusan Meclislerine aittir."),
        (9, "Kanun-ı Esasi", "1876 Kanun-ı Esasi'nin padişaha tanıdığı iki yetki nedir?", "Padişah kanunları sınırsız veto edebilir ve meclisi kapatabilir."),
        (9, "II. Abdülhamit", "II. Abdülhamit döneminde kurulan haber alma örgütünün adı nedir?", "Jurnal Teşkilatı, yani Hafiyelik Teşkilatıdır."),
        (9, "II. Abdülhamit", "Memleket Sandıkları hangi kuruma dönüştürülmüştür?", "Ziraat Bankasına dönüştürülmüştür."),
        (9, "II. Abdülhamit", "II. Abdülhamit'in dış politikada benimsediği fikir akımı hangisidir?", "İslamcılık, yani ümmetçiliktir."),
        (10, "II. Abdülhamit", "II. Abdülhamit döneminde yapımına başlanan demir yolu projesi hangisidir?", "Berlin-Bağdat Demir Yolu, yani 3B projesidir."),
        (10, "II. Abdülhamit", "Osmanlı'daki ilk sosyal yardım kurumu olarak kabul edilen kurum hangisidir?", "Darülaceze'dir."),
        (10, "II. Abdülhamit", "Muharrem Kararnamesi'nin ardından kurulan borç idaresi hangisidir?", "Düyun-u Umumiye İdaresi'dir."),
        (10, "II. Meşrutiyet", "II. Meşrutiyet hangi olayın ardından ilan edilmiştir?", "Reval Görüşmeleri sonrası Selanik ve Makedonya'daki İttihat ve Terakki hareketinin baskısıyla ilan edilmiştir."),
        (10, "II. Meşrutiyet", "31 Mart Vakası'nı bastıran askerî güç hangisidir?", "Selanik'ten gelen Hareket Ordusu'dur."),
        (10, "II. Meşrutiyet", "31 Mart Vakası sonucunda tahta kim çıkmıştır?", "II. Abdülhamit tahttan indirilmiş, yerine V. Mehmet Reşat geçmiştir."),
        (11, "II. Meşrutiyet", "1909 anayasa değişiklikleriyle hükümet kime karşı sorumlu hâle gelmiştir?", "Meclise karşı sorumlu hâle gelmiştir."),
        (11, "II. Meşrutiyet", "1909 değişiklikleriyle padişahın hangi iki yetkisi sınırlandırılmıştır?", "Meclisi kapatma yetkisi izne bağlanmış, sürgün ve angarya cezaları kaldırılmıştır."),
        (11, "Fikir akımları", "Osmanlıcılık düşüncesinin temel amacı nedir?", "Din ve ırk ayrımı yapmadan herkesi Osmanlı vatandaşı sayarak devleti bir arada tutmaktır."),
        (11, "Fikir akımları", "Türkçülük fikrinin önemli savunucularından üçünü yazınız.", "Yusuf Akçura, İsmail Gaspıralı, Ziya Gökalp, Halide Edip, Fuad Köprülü, Zeki Velidi Togan ve Ahmet Ağaoğlu savunucular arasındadır."),
        (11, "Fikir akımları", "“Ya Batılılaşırız ya mahvoluruz.” anlayışı hangi fikir akımıyla ilişkilidir?", "Batıcılık düşüncesiyle ilişkilidir."),
        (11, "Fikir akımları", "Adem-i merkeziyet fikrini savunan kişi kimdir?", "Prens Sabahattin'dir."),
        (12, "Trablusgarp", "Trablusgarp Savaşı'nın başlıca nedenlerinden ikisini yazınız.", "İtalya'nın sömürge arayışı ve Trablusgarp'ın İtalya'ya yakın, Osmanlı açısından savunulması güç bir konumda olmasıdır."),
        (12, "Trablusgarp", "Osmanlı Devleti Trablusgarp'a düzenli ordu gönderemeyince bölgede nasıl mücadele etmiştir?", "Gönüllü subaylar görevlendirmiştir."),
        (12, "Trablusgarp", "Mustafa Kemal Trablusgarp Savaşı'na hangi takma adla katılmıştır?", "Gazeteci Şerif Bey adıyla katılmıştır."),
        (12, "Trablusgarp", "Mustafa Kemal'in Trablusgarp'ta ilk savaştığı yer neresidir?", "Derne ve Tobruk'ta savaşmıştır."),
        (12, "Trablusgarp", "Dünya tarihinde ilk savaş uçağının kullanıldığı savaş hangisidir?", "Trablusgarp Savaşı'dır; İtalya tarafından kullanılmıştır."),
        (13, "Uşi Antlaşması", "Uşi Antlaşması ile Trablusgarp ve Bingazi'nin statüsü ne olmuştur?", "İtalya'ya bırakılmıştır."),
        (13, "Uşi Antlaşması", "Uşi Antlaşması'nda halifelik bağını sürdürmek için yapılan düzenleme nedir?", "Trablusgarp halkı dinî bakımdan halifeye bağlı kalmış, bölgede halifeyi temsilen naibü's-sultan görevlendirilmiştir."),
        (13, "Uşi Antlaşması", "Uşi Antlaşması ile On İki Ada'nın geçici olarak bırakıldığı devlet hangisidir?", "İtalya'dır; Balkan Savaşları sonuna kadar İtalya'da kalması kabul edilmiştir."),
        (13, "I. Balkan Savaşı", "I. Balkan Savaşı'nı başlatan devlet hangisidir?", "Karadağ'dır."),
        (13, "I. Balkan Savaşı", "I. Balkan Savaşı'nda en kârlı çıkan Balkan devleti hangisidir?", "Bulgaristan'dır."),
        (13, "I. Balkan Savaşı", "I. Balkan Savaşı sonunda Osmanlı Devleti'nin Balkanlardaki toprakları için genel sonuç nedir?", "Osmanlı Devleti Balkanlardaki topraklarının büyük bölümünü kaybetmiştir."),
        (14, "Balkan Savaşları", "1913 Londra Antlaşması ile Osmanlı-Bulgaristan sınırı hangi hat olarak belirlenmiştir?", "Midye-Enez hattı olarak belirlenmiştir."),
        (14, "Balkan Savaşları", "Osmanlı Devleti'nden ayrılan son Balkan ülkesi hangisidir?", "Arnavutluk'tur."),
        (14, "II. Balkan Savaşı", "I. Balkan Savaşı'na katılmayıp II. Balkan Savaşı'na katılan devlet hangisidir?", "Romanya'dır."),
        (14, "II. Balkan Savaşı", "II. Balkan Savaşı'ndan yararlanan Osmanlı Devleti Bulgaristan'dan hangi üç yeri geri almıştır?", "Edirne, Kırklareli ve Dimetoka'yı geri almıştır."),
        (14, "Balkan Savaşları", "I. Balkan Savaşı'nda Yunanların silah sevkiyatına zarar veren Rauf Orbay'a verilen unvan nedir?", "Hamidiye Kahramanı unvanıdır."),
        (15, "Balkan Savaşları", "29 Eylül 1913 İstanbul Antlaşması hangi iki devlet arasında imzalanmıştır ve sonucu nedir?", "Osmanlı ile Bulgaristan arasında imzalanmış; Meriç Nehri sınır kabul edilerek Edirne, Kırklareli ve Dimetoka Osmanlı'da kalmıştır."),
        (15, "Balkan Savaşları", "14 Kasım 1913 Atina Antlaşması hangi devletle yapılmıştır?", "Yunanistan'la yapılmıştır; Ege adalarının geleceği büyük devletlere bırakılmıştır."),
        (15, "I. Dünya Savaşı", "I. Dünya Savaşı'nın bloklaşma nedenlerinden biri olan Alsas-Loren Sorunu hangi iki devlet arasındadır?", "Almanya ile Fransa arasındadır."),
        (15, "I. Dünya Savaşı", "I. Dünya Savaşı'nda savaştan çekilen ilk ve savaşa son katılan devletler hangileridir?", "Savaştan ilk çekilen Bulgaristan, savaşa son katılan Yunanistan'dır."),
        (16, "I. Dünya Savaşı", "Almanya'nın Osmanlı Devleti'ni savaşa sokmak istemesinin iki nedeni nedir?", "Yeni cepheler açarak yükünü hafifletmek ve Osmanlı'nın jeopolitik, dinî ve demografik gücünden yararlanmaktır."),
        (16, "I. Dünya Savaşı", "Osmanlı Devleti'nin Almanya yanında savaşa girmesinde etkili olan siyasi etkenlerden ikisi nedir?", "Siyasi yalnızlıktan kurtulma isteği ve Almanya ile yapılan gizli antlaşmadır."),
        (16, "I. Dünya Savaşı", "Osmanlı Devleti'nin savaşa fiilen girmesine yol açan iki Alman gemisi hangileridir?", "Goeben ve Breslau'dur; Osmanlı'da Yavuz ve Midilli adlarını almıştır."),
        (16, "Kafkasya Cephesi", "Kafkasya Cephesi'nin açılma amaçlarından biri nedir?", "Elviye-i Selase'yi, yani Kars-Ardahan-Batum'u geri almak amaçlanmıştır."),
        (16, "Kafkasya Cephesi", "Brest-Litovsk Antlaşması ile Osmanlı Devleti'ne geri verilen yerler hangileridir?", "Kars, Ardahan ve Batum geri verilmiştir."),
        (17, "Kanal Cephesi", "Kanal Cephesi'nin açılma amaçları nelerdir?", "İngiltere'nin işgalindeki Mısır'ı geri almak ve İngiltere'nin sömürgeleriyle bağını kesmektir."),
        (17, "Suriye-Filistin Cephesi", "Suriye-Filistin Cephesi'nin Mustafa Kemal bakımından ayırt edici yönü nedir?", "Mustafa Kemal'in I. Dünya Savaşı'ndaki son savaştığı cephe olmasıdır."),
        (17, "Çanakkale Cephesi", "Çanakkale Savaşı'nın diğer adlarından ikisini yazınız.", "Centilmenler Savaşı, Aydınlar Savaşı ve Dardanelya Savaşı adlarıyla da anılır."),
        (17, "Çanakkale Cephesi", "İtilaf Devletleri Çanakkale Cephesi'ni açarak hangi temel hedefe ulaşmak istemiştir?", "Rusya'ya Boğazlar üzerinden yardım göndermek ve Osmanlı'yı savaş dışı bırakmak istemiştir."),
        (18, "Çanakkale Cephesi", "Çanakkale Savaşı'nın savaşın geneli bakımından en önemli sonucu nedir?", "Savaşın süresi en az iki yıl uzamış, Bulgaristan Osmanlı'nın yanında savaşa girmiş ve Almanya-Osmanlı kara bağlantısı kurulmuştur."),
        (18, "Çanakkale Cephesi", "Mustafa Kemal Çanakkale Savaşı sonunda hangi rütbeye yükselmiş, hangi unvanı almıştır?", "Albaylığa yükselmiş ve Anafartalar Kahramanı unvanını almıştır."),
        (18, "Irak Cephesi", "Kut'ül Amare Zaferi hangi cephede kazanılmıştır?", "Irak Cephesi'nde kazanılmıştır."),
        (18, "Irak Cephesi", "Kut'ül Amare Zaferi'nden dolayı Halil Paşa'ya hangi unvan verilmiştir?", "Kut'ül Amare Kahramanı unvanı verilmiştir."),
        (19, "Hicaz-Yemen Cephesi", "Hicaz-Yemen Cephesi'nde İngilizlerin Arapları kışkırtmak için kullandığı kişi kimdir?", "Arabistanlı Lawrence'tır."),
        (19, "Hicaz-Yemen Cephesi", "Şerif Hüseyin ile İngiltere arasında yapılan gizli antlaşma hangisidir?", "Mac Mahon Antlaşması'dır."),
        (19, "Gizli antlaşmalar", "Sykes-Picot Antlaşması hangi devletler arasında imzalanmıştır?", "İngiltere ve Fransa arasında imzalanmış, daha sonra Rusya da antlaşmaya dâhil olmuştur."),
        (19, "Gizli antlaşmalar", "Sykes-Picot Antlaşması'nda Boğdat, Basra ve Güney Irak hangi devlete bırakılmıştır?", "İngiltere'ye bırakılmıştır."),
        (19, "Gizli antlaşmalar", "Saint Jean de Maurienne Antlaşması ile İtalya'ya bırakılması öngörülen bölge neresidir?", "Güneybatı Anadolu, yani İzmir ve çevresidir."),
        (19, "Gizli antlaşmalar", "I. Dünya Savaşı sırasındaki gizli antlaşmalar hangi adla dünya kamuoyuna açıklanmıştır?", "Sarı Kitap adıyla Sovyet Rusya tarafından açıklanmıştır."),
        (20, "Wilson İlkeleri", "Wilson İlkeleri'nde öngörülen uluslararası teşkilat hangisidir?", "Cemiyet-i Akvam, yani Milletler Cemiyetidir."),
        (20, "Wilson İlkeleri", "Wilson İlkeleri'nin 12. maddesi Osmanlı için hangi ilkeyi öne çıkarır?", "Türklerin çoğunlukta olduğu yerlerin Türklere, azınlıkların çoğunlukta olduğu yerlerin ise azınlıklara bırakılması ilkesini öne çıkarır."),
        (20, "I. Dünya Savaşı sonuçları", "I. Dünya Savaşı sonunda en kârlı ve en zararlı çıkan devletler hangileridir?", "En kârlı çıkanlar İngiltere, Japonya ve Fransa; en zararlı çıkan devlet Almanya'dır."),
        (20, "I. Dünya Savaşı sonuçları", "I. Dünya Savaşı sonunda parçalanan dört imparatorluk hangileridir?", "Almanya, Osmanlı Devleti, Rusya ve Avusturya-Macaristan'dır."),
        (20, "I. Dünya Savaşı sonuçları", "Mondros Ateşkes Antlaşması hangi devletle imzalanmıştır?", "Osmanlı Devleti ile imzalanmıştır."),
        (21, "Mondros", "Mondros Ateşkes Antlaşması Osmanlı adına kim tarafından imzalanmıştır?", "Rauf Orbay tarafından imzalanmıştır."),
        (21, "Mondros", "Mondros Ateşkes Antlaşması'nın 7. maddesi İtilaf Devletlerine hangi imkânı vermiştir?", "Güvenliklerini tehdit eden herhangi bir yeri işgal etme imkânı vermiştir."),
        (21, "Mondros", "Mondros Ateşkes Antlaşması'nın 24. maddesi hangi amaçla ilişkilendirilir?", "Vilayet-i Sitte'de karışıklık çıkması hâlinde işgal hakkı tanıyarak Megali Ermenistan kurulmasına zemin hazırlamakla ilişkilendirilir."),
        (21, "Mondros", "Mondros'tan sonra işgale uğrayan ilk Osmanlı toprağı neresidir?", "Musul'dur; İngiltere tarafından işgal edilmiştir."),
        (21, "Mondros", "Kara Mehmet Çavuş hangi bölgenin işgaline karşı ilk kurşunu atmıştır?", "Hatay'ın Dörtyol ilçesinde Fransızlara karşı atmıştır."),
        (22, "Paris Barış Konferansı", "Paris Barış Konferansı'nda İtilaf Devletleri arasında ilk görüş ayrılığı hangi bölge konusunda yaşanmıştır?", "İzmir ve çevresi konusunda yaşanmıştır."),
        (22, "Paris Barış Konferansı", "Paris Barış Konferansı sonucunda kurulan uluslararası örgüt hangisidir?", "Milletler Cemiyeti, yani Cemiyet-i Akvamdır."),
        (22, "İzmir'in işgali", "İzmir'in işgalinden sonra olayı araştırmak üzere gönderilen heyetin hazırladığı rapor hangisidir?", "Amiral Bristol Raporu'dur."),
        (22, "Yararlı cemiyetler", "Yararlı cemiyetlerin Wilson İlkeleri bakımından ortak hedefi nedir?", "Wilson İlkeleri'nin 12. maddesinden yararlanarak bölgelerinin Türk yurdu olduğunu göstermek ve halk desteğini sağlamaktır."),
        (22, "Yararlı cemiyetler", "Sivas Kongresi'nde Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti içinde birleştirilen cemiyetler hangi türdedir?", "Yararlı cemiyetlerdir."),
        (23, "Yararlı cemiyetler", "İzmir Müdafaa-i Hukuk-ı Osmaniye Cemiyeti hangi amaçla kurulmuştur?", "İzmir'in Yunanistan tarafından ilhak edilmesini önlemek amacıyla kurulmuştur."),
        (23, "Yararlı cemiyetler", "Reddi-i İlhak Cemiyeti hangi gelişme üzerine kurulmuştur?", "İzmir Müdafaa-i Hukuk-ı Osmaniye Cemiyetinin yerine, İzmir'in işgalinden bir gün önce kurulmuştur."),
        (23, "Yararlı cemiyetler", "Trabzon Muhafaza-i Hukuk Cemiyeti hangi devleti engellemek için kurulmuştur?", "Pontus Rum Devleti'nin kurulmasını engellemek için kurulmuştur."),
        (23, "Yararlı cemiyetler", "Vilayat-ı Şarkiye Müdafaa-i Hukuk-ı Milliye Cemiyeti hangi tehdide karşı kurulmuştur?", "Doğu Anadolu'da bağımsız bir Ermeni devleti kurulması tehdidine karşı kurulmuştur."),
        (23, "Yararlı cemiyetler", "Kilikyalılar Cemiyeti hangi bölgenin Ermenilere verilmesini engellemek için kurulmuştur?", "Adana ve çevresinin Ermenilere verilmesini engellemek için kurulmuştur."),
        (23, "Yararlı cemiyetler", "Anadolu Kadınları Müdafaa-i Hukuk Cemiyeti'nin kuruluşunda emeği geçen kadın kimdir?", "Sivas Valisi Reşit Bey'in eşi Melek Reşit Hanım'dır."),
        (23, "Yararlı cemiyetler", "Kars İslam Şûrası'nın tarihi açıdan önemi nedir?", "İlk yararlı cemiyet kabul edilir; kısa süreli Cenubi Garbi Kafkas Hükümeti'ni kurmuştur."),
        (24, "Zararlı cemiyetler", "Etnik-i Eterya Cemiyeti hangi amaçla kurulmuştur?", "Megali İdea'yı, yani Büyük Yunanistan'ı gerçekleştirmek amacıyla kurulmuştur."),
        (24, "Zararlı cemiyetler", "Mavri Mira Cemiyeti hangi ideal doğrultusunda çalışmıştır?", "Megali İdea doğrultusunda çalışmıştır."),
        (24, "Zararlı cemiyetler", "Pontus Rum Cemiyeti'nin temel amacı nedir?", "İnebolu'dan Batum'a uzanan sahada Samsun merkezli Pontus Rum İmparatorluğu kurmaktır."),
        (24, "Zararlı cemiyetler", "Hınçak ve Taşnak cemiyetlerinin ortak hedefi nedir?", "Doğu Anadolu'da bağımsız bir Ermeni devleti kurmaktır."),
        (24, "Zararlı cemiyetler", "Maccabi Cemiyeti hangi amaçla kurulmuştur?", "Anadolu'daki Yahudilerin haklarını korumak ve Filistin'de bir Yahudi devleti kurmak amacıyla kurulmuştur."),
        (24, "Zararlı cemiyetler", "Kürt Teali Cemiyeti hangi bölge için devlet kurmayı amaçlamıştır?", "Güneydoğu Anadolu'da bir Kürt devleti kurmayı amaçlamıştır."),
        (25, "Hazırlık dönemi", "Mustafa Kemal Samsun'a hangi görevle çıkmıştır?", "9. Ordu Müfettişi, yani 3. Ordu Müfettişi göreviyle çıkmıştır."),
        (25, "Hazırlık dönemi", "Mustafa Kemal'in Samsun'a çıkışındaki resmî görevlerinden ikisini yazınız.", "Bölgede asayişi sağlamak, silah ve cephaneyi toplatmak, komitelerin faaliyetlerini bitirmek ve iç güvenlik sorunlarının nedenini araştırmak görevleri arasındadır."),
        (25, "Havza Genelgesi", "Havza Genelgesi'nin yayımlanış biçimi ve temel amacı nedir?", "Mustafa Kemal tarafından tek başına yayımlanmış; millî bilinci uyandırmak amacıyla hazırlanmıştır."),
        (25, "Havza Genelgesi", "Havza Genelgesi'nde protestolar için getirilen sınırlama nedir?", "Protestolar sırasında masum azınlıklara zarar verilmemesi istenmiştir."),
        (25, "Amasya Genelgesi", "Amasya Genelgesi kimler tarafından yayımlanmıştır?", "Mustafa Kemal ile silah arkadaşları tarafından birlikte yayımlanmıştır."),
        (25, "Amasya Genelgesi", "Amasya Genelgesi'nde millî mücadelenin gerekçesini açıklayan ifade nedir?", "“Vatanın bütünlüğü, milletin istiklali tehlikededir.” ifadesidir."),
        (25, "Amasya Genelgesi", "Amasya Genelgesi'nde Millî Mücadele'nin yöntemini belirleyen karar nedir?", "“Milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır.” kararıdır."),
        (26, "Amasya Genelgesi", "Amasya Genelgesi Millî Mücadele bakımından neden ihtilal bildirisi sayılır?", "Millî Mücadele'nin gerekçesi, amacı ve yöntemi belirlendiği için ihtilal bildirisi sayılır."),
        (26, "Amasya Genelgesi", "Amasya Genelgesi'nde ilk kez değinilen yönetim ilkesi nedir?", "Üstü kapalı biçimde ulusal egemenliğe dayalı bir devlet rejimine ilk kez değinilmiştir."),
        (26, "Amasya Genelgesi", "Amasya Genelgesi'nde Sivas'ta toplanması kararlaştırılan kongre için kimlerin seçileceği belirtilmiştir?", "Her sancaktan halkın güvenini kazanmış belediye ve cemiyetlerce belirlenen üç temsilcinin gönderileceği belirtilmiştir."),
        (26, "Erzurum Kongresi", "Mustafa Kemal Erzurum Kongresi'ne katılmadan önce hangi görevinden ve meslekten ayrılmıştır?", "9. Ordu Müfettişliğinden ve askerlik mesleğinden istifa etmiştir."),
        (27, "Erzurum Kongresi", "Erzurum Kongresi'ni toplayan iki yararlı cemiyet hangileridir?", "Trabzon Muhafaza-i Hukuk-ı Milliye ve Vilayat-ı Şarkiye Müdafaa-i Hukuk-ı Milliye cemiyetleridir."),
        (27, "Erzurum Kongresi", "Erzurum Kongresi'nin toplanış amacı ve kararları bakımından niteliği nedir?", "Toplanış amacı bakımından bölgesel, aldığı kararlar bakımından ulusaldır."),
        (27, "Erzurum Kongresi", "Erzurum Kongresi'nde ilk kez kabul edilen iki temel ilke nedir?", "Manda ve himayenin kabul edilemeyeceği ve ulusal iradeyi hâkim kılmanın esas olduğu ilkeleridir."),
        (27, "Erzurum Kongresi", "Erzurum Kongresi'nde kurulması kararlaştırılan Temsil Heyetinin başkanı kimdir?", "Mustafa Kemal'dir."),
        (27, "Erzurum Kongresi", "Erzurum Kongresi'nde İstanbul Hükûmeti görevini yapmazsa nasıl bir çözüm öngörülmüştür?", "Her türlü etki ve denetimden uzak geçici bir hükûmet kurulması öngörülmüştür."),
        (28, "Balıkesir-Alaşehir", "Balıkesir Kongreleri'nin Millî Mücadele bakımından önemli sonucu nedir?", "Batı Cephesi kurulmuştur."),
        (28, "Balıkesir-Alaşehir", "Balıkesir Kongrelerinde Yunanlara karşı yardım alma konusunda hangi karar alınmıştır?", "Gereğinde İtilaf Devletlerinden yardım alınabileceği kararı alınmıştır."),
        (28, "Sivas Kongresi", "Sivas Kongresi'nin toplanış amacı ve kararları bakımından niteliği nedir?", "Hem toplanış amacı hem de aldığı kararlar bakımından ulusaldır."),
        (28, "Sivas Kongresi", "Sivas Kongresi'nde Erzurum Kongresi kararları için ne yapılmıştır?", "Erzurum Kongresi kararları genişletilerek kabul edilmiştir."),
        (28, "Sivas Kongresi", "Sivas Kongresi'nde yararlı cemiyetler hangi çatı altında birleştirilmiştir?", "Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adı altında birleştirilmiştir."),
        (28, "Sivas Kongresi", "Sivas Kongresi'nde Temsil Heyeti ilk kez hangi yetkiyi kullanmıştır?", "Yürütme yetkisini kullanmıştır."),
        (29, "Sivas Kongresi", "Sivas Kongresi'nde manda ve himaye konusunda hangi karar alınmıştır?", "Manda ve himaye kesin olarak bir daha gündeme gelmemek üzere reddedilmiştir."),
        (29, "Sivas Kongresi", "Sivas Kongresi'nden sonra Millî Mücadele lehine İstanbul Hükûmetine karşı kazanılan ilk siyasi zafer nedir?", "Damat Ferit Paşa Hükûmetinin düşürülüp yerine Ali Rıza Paşa Hükûmetinin kurulmasıdır."),
        (29, "Millî Mücadele basını", "İrade-i Milliye gazetesi nerede ve hangi amaçla çıkarılmıştır?", "Sivas'ta, Millî Mücadele'nin önemini halka anlatmak için çıkarılmıştır."),
        (29, "Millî Mücadele basını", "Hakimiyet-i Milliye'nin Millî Mücadele basını içindeki özelliği nedir?", "İrade-i Milliye'nin devamı ve TBMM'nin yarı resmî yayın organı olmasıdır."),
        (29, "Millî Mücadele basını", "Mustafa Kemal ve Ali Fethi Okyar'ın İstanbul'da çıkardığı gazete hangisidir?", "Minber gazetesidir."),
        (29, "Millî Mücadele basını", "Millî Mücadele aleyhindeki en sert yazıların çıktığı gazete hangisidir?", "Peyam-ı Sabah gazetesidir."),
        (30, "Amasya Görüşmeleri", "Amasya Görüşmeleri sonucunda Temsil Heyeti hangi hükûmet tarafından resmen tanınmıştır?", "Ali Rıza Paşa Hükûmeti tarafından resmen tanınmıştır."),
        (30, "Amasya Görüşmeleri", "Amasya Görüşmeleri'nde alınan seçim kararı nedir?", "Kapatılan Osmanlı Mebusan Meclisinin açılması ve ülke genelinde seçim yapılması kararlaştırılmıştır."),
        (30, "Amasya Görüşmeleri", "Mustafa Kemal'in Ankara'yı Millî Mücadele merkezi seçmesinde etkili üç nedenden ikisini yazınız.", "Ulaşım-haberleşme imkânı, Batı Cephesi'ne yakınlık, işgale uğramamış güvenli bölge oluşu ve düzenli kolordu bulunması etkili olmuştur."),
        (30, "Amasya Görüşmeleri", "Mustafa Kemal İstanbul'a gidecek heyetten hangi iki istekte bulunmuştur?", "Kendisinin meclis başkanı seçilmesini ve Müdafaa-i Hukuk yanlısı bir grup kurulmasını istemiştir."),
        (31, "Misak-ı Millî", "Misak-ı Millî kimler tarafından hazırlanmıştır?", "Mustafa Kemal ile Mebusan Meclisi milletvekilleri tarafından birlikte hazırlanmıştır."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nin Osmanlı Mebusan Meclisindeki yeri nedir?", "Mebusan Meclisinde kabul edilen son kanundur."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nde vatan sınırları hangi tarih esas alınarak belirlenmiştir?", "Mondros Ateşkes Antlaşması'nın imzalandığı 30 Ekim 1918 tarihindeki işgal edilmemiş yerler bütün kabul edilmiştir."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nde halkoyuna bırakılması öngörülen üç sancak hangileridir?", "Kars, Ardahan ve Batum'dur."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nde Batı Trakya'nın geleceği için hangi yöntem öngörülmüştür?", "Halkın serbestçe vereceği oy, yani halk oylaması öngörülmüştür."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nde kapitülasyonlar için ne istenmiştir?", "Millî ve ekonomik gelişmeyi engelleyen siyasi, adli ve mali sınırlamaların, yani kapitülasyonların kaldırılması istenmiştir."),
        (31, "Misak-ı Millî", "Misak-ı Millî'nde ulus egemenliği için doğrudan bir karar var mıdır?", "Hayır. Misak-ı Millî'nde ulus egemenliğine doğrudan yönelik bir karar bulunmaz.")
    ]
}
